-- Designing a URL Shortener
insert into public.articles (owner_id, public_id, title) values ('00000000-0000-4000-a000-000000000002', 'UrlShort3ner', 'Designing a URL Shortener');
-- (separate statements: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-5","frameId":"url-shortener-frame-1"},"content":[{"type":"text","text":"Requirements"}]},{"type":"paragraph","content":[{"type":"text","text":"Users submit a long URL and get a short alias; visiting the alias redirects to the original."}],"attrs":{"blockId":"url-shortener-b-2"}},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"100M new URLs a month"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Reads outnumber writes 100 : 1"}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Redirect under 50 ms"}]}]}],"attrs":{"blockId":"url-shortener-b-3"}},{"type":"paragraph","content":[{"type":"text","text":"Non-goals for v1: custom domains, analytics dashboards and editing a link after it is created."}],"attrs":{"blockId":"url-shortener-b-4"}},{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-f","frameId":"url-shortener-frame-b"},"content":[{"type":"text","text":"High-level design"}]},{"type":"paragraph","content":[{"type":"text","text":"Clients call a stateless API service behind a load balancer. Short codes map to long URLs in a key-value store."}],"attrs":{"blockId":"url-shortener-b-c"}},{"type":"callout","attrs":{"tone":"mint","blockId":"url-shortener-b-d"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Key idea: generate IDs from a counter and encode them in base62 — 7 characters give 3.5 trillion codes."}]}]},{"type":"details","attrs":{"tone":"sky","blockId":"url-shortener-b-e"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why not hash the long URL?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Hashes collide and need a retry loop; a counter never collides and keeps codes short."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"url-shortener-s-r","frameId":"url-shortener-frame-o"},"content":[{"type":"text","text":"Scaling reads"}]},{"type":"paragraph","content":[{"type":"text","text":"Most traffic is redirects, so cache hot codes at the edge and in Redis; misses go to read replicas."}],"attrs":{"blockId":"url-shortener-b-p"}},{"type":"callout","attrs":{"tone":"red","blockId":"url-shortener-b-q"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Watch out: cache 301 redirects carefully — browsers keep them forever."}]}]}]}'::jsonb, canvas = '{"layout":"50-50","files":{},"elements":[{"id":"url-shortener-frame-1","type":"frame","x":0,"y":0,"width":1400,"height":1400,"name":"Requirements","seed":1,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"url-shortener-el-6","frameId":"url-shortener-frame-1","seed":1586866354,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":120,"y":220,"width":320,"height":130,"strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-7","frameId":"url-shortener-frame-1","seed":1603643973,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":191.76,"y":267.5,"width":176.48000000000002,"height":35,"text":"Shorten URL","originalText":"Shorten URL","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-8","frameId":"url-shortener-frame-1","seed":1620421592,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":540,"y":220,"width":320,"height":130,"strokeColor":"#b45309","background