originalText":"Key-value store","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-n","frameId":"url-shortener-frame-b","seed":915761594,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":8260,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false},{"id":"url-shortener-frame-o","type":"frame","x":14800,"y":0,"width":1400,"height":1400,"name":"Scaling reads","seed":3,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"url-shortener-el-s","frameId":"url-shortener-frame-o","seed":462765881,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":14920,"y":220,"width":320,"height":130,"strokeColor":"#0f766e","backgroundColor":"#ccfbf1","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-t","frameId":"url-shortener-frame-o","seed":479543500,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":14991.76,"y":267.5,"width":176.48000000000002,"height":35,"text":"CDN / cache","originalText":"CDN / cache","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-u","frameId":"url-shortener-frame-o","seed":496321119,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"rectangle","x":15340,"y":220,"width":320,"height":130,"strokeColor":"#b45309","backgroundColor":"#fef3c7","fillStyle":"solid","strokeWidth":2,"roundness":{"type":3}},{"id":"url-shortener-el-v","frameId":"url-shortener-frame-o","seed":513098738,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":15396.08,"y":267.5,"width":207.84000000000003,"height":35,"text":"Read replicas","originalText":"Read replicas","fontSize":28,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"url-shortener-el-w","frameId":"url-shortener-frame-o","seed":529876357,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"arrow","x":15240,"y":285,"width":96,"height":0,"points":[[0,0],[96,0]],"strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roundness":null,"lastCommittedPoint":null,"startArrowhead":null,"endArrowhead":"arrow","elbowed":false}]}'::jsonb, version = version + 1, updated_at = now()
