-- Consistent Hashing
insert into public.articles (owner_id, public_id, title) values ('00000000-0000-4000-a000-000000000002', 'CnsHashing01', 'Consistent Hashing');
-- (separate statements: the draft row is created by the on_article_created trigger)
update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-g","frameId":"consistent-hashing-frame-1"},"content":[{"type":"text","text":"Why naive hashing breaks"}]},{"type":"paragraph","content":[{"type":"text","text":"Imagine you run "},{"type":"text","text":"N cache servers","marks":[{"type":"bold"}]},{"type":"text","text":" in front of a database. For every key you must decide which server stores it."}],"attrs":{"blockId":"consistent-hashing-b-2"}},{"type":"paragraph","content":[{"type":"text","text":"The obvious rule is "},{"type":"text","text":"server = hash(key) % N","marks":[{"type":"code"}]},{"type":"text","text":". It is fast, needs no shared state, and every client computes the same answer."}],"attrs":{"blockId":"consistent-hashing-b-3"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-4"},"content":[{"type":"text","text":"The problem: N changes"}]},{"type":"paragraph","content":[{"type":"text","text":"The rule works until "},{"type":"text","text":"N changes","marks":[{"type":"bold"}]},{"type":"text","text":". You add a server because traffic grew, or you lose one because it crashed."}],"attrs":{"blockId":"consistent-hashing-b-5"}},{"type":"paragraph","content":[{"type":"text","text":"Suddenly almost every key maps to a different server. The caches are effectively empty, every request falls through to the database at the same moment, and the database can fall over. This is called a "},{"type":"text","text":"cache stampede","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-6"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-7"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"The drawing takes 8 keys, "},{"type":"text","text":"k1 to k8","marks":[{"type":"bold"}]},{"type":"text","text":", whose hashes are 10 to 17. The "},{"type":"text","text":"% 3","marks":[{"type":"code"}]},{"type":"text","text":" column shows their server with 3 servers (S0–S2), and the "},{"type":"text","text":"% 4","marks":[{"type":"code"}]},{"type":"text","text":" column shows it after adding a fourth server (S3)."}],"attrs":{"blockId":"consistent-hashing-b-8"}},{"type":"paragraph","content":[{"type":"text","text":"The red rows are the keys that changed server: "},{"type":"text","text":"5 of the 8 keys moved","marks":[{"type":"bold"}]},{"type":"text","text":", even though we only added one server."}],"attrs":{"blockId":"consistent-hashing-b-9"}},{"type":"callout","attrs":{"tone":"red","blockId":"consistent-hashing-b-a"},"content":[{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"% N","marks":[{"type":"code"}]},{"type":"text","text":", going from N to N+1 servers moves about "},{"type":"text","text":"N/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":" of all keys: 75% when growing from 3 to 4 servers, and 99% when growing from 100 to 101."}]}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Servers (before → after)"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys moved with "},{"type":"text","text":"% N","marks":[{"type":"code"}]}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Keys moved with consistent hashing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"3 → 4"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"75%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"25%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"10 → 11"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"91%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"9%"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"100 → 101"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"99%"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"1%"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-b"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-c"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why does modulo move N/(N+1) of the keys?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"A key stays on the same server only if "},{"type":"text","text":"h % N == h % (N+1)","marks":[{"type":"code"}]},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"For uniformly random hashes that happens for N out of every N·(N+1) values, so with probability "},{"type":"text","text":"1/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":". The fraction that moves is therefore "},{"type":"text","text":"1 − 1/(N+1) = N/(N+1)","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-d"},"content":[{"type":"text","text":"What we want instead"}]},{"type":"paragraph","content":[{"type":"text","text":"When a server joins or leaves, "},{"type":"text","text":"only the keys that must move should move","marks":[{"type":"bold"}]},{"type":"text","text":". That is about "},{"type":"text","text":"K/N","marks":[{"type":"bold"}]},{"type":"text","text":" keys (K keys, N servers): exactly the new server''s fair share, shown in the green box in the drawing."}],"attrs":{"blockId":"consistent-hashing-b-e"}},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing guarantees this. It was introduced by Karger et al. at MIT in 1997 for web caching, and became the basis of Akamai''s CDN."}],"attrs":{"blockId":"consistent-hashing-b-f"}},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-3i","frameId":"consistent-hashing-frame-35"},"content":[{"type":"text","text":"The hash ring"}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing starts with one simple picture: the "},{"type":"text","text":"hash ring","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-36"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-37"},"content":[{"type":"text","text":"Bend the hash space into a circle"}]},{"type":"paragraph","content":[{"type":"text","text":"Take the output range of a hash function, for example "},{"type":"text","text":"0 to 2³²−1","marks":[{"type":"bold"}]},{"type":"text","text":", and bend it into a circle. After the largest value comes 0 again."}],"attrs":{"blockId":"consistent-hashing-b-38"}},{"type":"paragraph","content":[{"type":"text","text":"To keep numbers readable, the drawing shows positions as "},{"type":"text","text":"fractions of the ring","marks":[{"type":"bold"}]},{"type":"text","text":": 0 at the top, then 1/4, 1/2 and 3/4 going clockwise."}],"attrs":{"blockId":"consistent-hashing-b-39"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-3a"},"content":[{"type":"text","text":"Put servers and keys on the same ring"}]},{"type":"paragraph","content":[{"type":"text","text":"Now hash "},{"type":"text","text":"servers and keys with the same function","marks":[{"type":"bold"}]},{"type":"text","text":", so both land somewhere on the ring."}],"attrs":{"blockId":"consistent-hashing-b-3b"}},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"server''s","marks":[{"type":"bold"}]},{"type":"text","text":" position is the hash of its name or IP address."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"key''s","marks":[{"type":"bold"}]},{"type":"text","text":" position is the hash of the key itself."}]}]}],"attrs":{"blockId":"consistent-hashing-b-3c"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-3d"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"Server "},{"type":"text","text":"cache-A","marks":[{"type":"bold"}]},{"type":"text","text":" hashes to "},{"type":"text","text":"0.21","marks":[{"type":"bold"}]},{"type":"text","text":", so it sits a little before the 1/4 mark. Key "},{"type":"text","text":"user:42","marks":[{"type":"bold"}]},{"type":"text","text":" hashes to "},{"type":"text","text":"0.63","marks":[{"type":"bold"}]},{"type":"text","text":", a little after the halfway point."}],"attrs":{"blockId":"consistent-hashing-b-3e"}},{"type":"paragraph","content":[{"type":"text","text":"Both use the same hash function, which is why they can be compared on the same circle."}],"attrs":{"blockId":"consistent-hashing-b-3f"}},{"type":"callout","attrs":{"tone":"mint","blockId":"consistent-hashing-b-3g"},"content":[{"type":"paragraph","content":[{"type":"text","text":"The ring is only a picture. In code it is a "},{"type":"text","text":"sorted list of numbers","marks":[{"type":"bold"}]},{"type":"text","text":" that wraps around at the end."}]}]},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-3h"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Which hash function should you use?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"It must spread values "},{"type":"text","text":"uniformly","marks":[{"type":"bold"}]},{"type":"text","text":", and give the "},{"type":"text","text":"same result on every machine and in every language","marks":[{"type":"bold"}]},{"type":"text","text":", because all clients must agree."}]},{"type":"paragraph","content":[{"type":"text","text":"Common choices are "},{"type":"text","text":"MurmurHash3","marks":[{"type":"bold"}]},{"type":"text","text":" or "},{"type":"text","text":"xxHash","marks":[{"type":"bold"}]},{"type":"text","text":" (fast, not cryptographic), or the first bytes of "},{"type":"text","text":"MD5","marks":[{"type":"bold"}]},{"type":"text","text":" (used by the classic memcached "},{"type":"text","text":"ketama","marks":[{"type":"italic"}]},{"type":"text","text":" library)."}]},{"type":"paragraph","content":[{"type":"text","text":"Never use a language''s built-in "},{"type":"text","text":"hashCode()","marks":[{"type":"code"}]},{"type":"text","text":" or "},{"type":"text","text":"hash()","marks":[{"type":"code"}]},{"type":"text","text":": it can differ between processes, versions or platforms."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-4j","frameId":"consistent-hashing-frame-48"},"content":[{"type":"text","text":"Finding a key''s server"}]},{"type":"paragraph","content":[{"type":"text","text":"Once servers and keys are on the ring, finding a key''s server takes one rule: "},{"type":"text","text":"walk clockwise","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-49"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-4a"},"content":[{"type":"text","text":"The rule"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash the key to get its position "},{"type":"text","text":"p","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find the first server whose position is "},{"type":"text","text":"≥ p","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If there is none, "},{"type":"text","text":"wrap around","marks":[{"type":"bold"}]},{"type":"text","text":" to the first server on the ring."}]}]}],"attrs":{"blockId":"consistent-hashing-b-4b"}},{"type":"paragraph","content":[{"type":"text","text":"That server owns the key. Put differently, every server owns the "},{"type":"text","text":"arc between the previous server and itself","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-4c"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-4d"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"Servers "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":", "},{"type":"text","text":"B","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"C","marks":[{"type":"bold"}]},{"type":"text","text":" each colour the arc they own: A owns (C, A], B owns (A, B] and C owns (B, C]."}],"attrs":{"blockId":"consistent-hashing-b-4e"}},{"type":"paragraph","content":[{"type":"text","text":"Key "},{"type":"text","text":"k3","marks":[{"type":"bold"}]},{"type":"text","text":" sits between B and C. Walking clockwise from k3, the first server we reach is C, so "},{"type":"text","text":"C owns k3","marks":[{"type":"bold"}]},{"type":"text","text":" (the dashed arrow)."}],"attrs":{"blockId":"consistent-hashing-b-4f"}},{"type":"paragraph","content":[{"type":"text","text":"Keys "},{"type":"text","text":"k4","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"k5","marks":[{"type":"bold"}]},{"type":"text","text":" sit after C. Walking clockwise passes the top of the ring (0) and reaches "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":": that is the wrap-around in step 3."}],"attrs":{"blockId":"consistent-hashing-b-4g"}},{"type":"callout","attrs":{"tone":"mint","blockId":"consistent-hashing-b-4h"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Every client that knows the same server list computes the same answer "},{"type":"text","text":"without asking anyone","marks":[{"type":"bold"}]},{"type":"text","text":". No central router is needed."}]}]},{"type":"paragraph","content":[{"type":"text","text":"This is why memcached client libraries could shard data on their own: each client simply carries the ring."}],"attrs":{"blockId":"consistent-hashing-b-4i"}},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-5u","frameId":"consistent-hashing-frame-5g"},"content":[{"type":"text","text":"Adding and removing servers"}]},{"type":"paragraph","content":[{"type":"text","text":"This is where consistent hashing pays off: a change in servers only affects "},{"type":"text","text":"one arc","marks":[{"type":"bold"}]},{"type":"text","text":" of the ring."}],"attrs":{"blockId":"consistent-hashing-b-5h"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-5i"},"content":[{"type":"text","text":"Adding a server"}]},{"type":"paragraph","content":[{"type":"text","text":"When a new server "},{"type":"text","text":"D","marks":[{"type":"bold"}]},{"type":"text","text":" lands between A and B, it takes over only the keys between A and D. Those keys used to belong to B."}],"attrs":{"blockId":"consistent-hashing-b-5j"}},{"type":"paragraph","content":[{"type":"text","text":"Every other key stays exactly where it was."}],"attrs":{"blockId":"consistent-hashing-b-5k"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-5l"},"content":[{"type":"text","text":"Removing a server"}]},{"type":"paragraph","content":[{"type":"text","text":"When a server leaves or crashes, its keys move to the "},{"type":"text","text":"next server clockwise","marks":[{"type":"bold"}]},{"type":"text","text":". Again, no other key moves."}],"attrs":{"blockId":"consistent-hashing-b-5m"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-5n"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"On the left are servers A, B and C with keys k1, k2 and k3. On the right, "},{"type":"text","text":"D (new)","marks":[{"type":"bold"}]},{"type":"text","text":" has been added between A and B."}],"attrs":{"blockId":"consistent-hashing-b-5o"}},{"type":"paragraph","content":[{"type":"text","text":"Only "},{"type":"text","text":"k1","marks":[{"type":"bold"}]},{"type":"text","text":" falls in D''s new arc, so only k1 moves from B to D. Keys k2 and k3 stay where they were."}],"attrs":{"blockId":"consistent-hashing-b-5p"}},{"type":"paragraph","content":[{"type":"text","text":"If D is removed again, k1 goes back to B, the next server clockwise."}],"attrs":{"blockId":"consistent-hashing-b-5q"}},{"type":"callout","attrs":{"tone":"mint","blockId":"consistent-hashing-b-5r"},"content":[{"type":"paragraph","content":[{"type":"text","text":"On average only "},{"type":"text","text":"K/N keys move","marks":[{"type":"bold"}]},{"type":"text","text":" (K keys, N servers). That is the minimum possible: the new server has to get its fair share from somewhere."}]}]},{"type":"paragraph","content":[{"type":"text","text":"The catch:","marks":[{"type":"bold"}]},{"type":"text","text":" a new server relieves only "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" neighbour, and a removed server dumps its whole load on "},{"type":"text","text":"one","marks":[{"type":"bold"}]},{"type":"text","text":" neighbour. With few servers that is very uneven. Virtual nodes, in the next section, fix it."}],"attrs":{"blockId":"consistent-hashing-b-5s"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-5t"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Worked example: 4 servers, 1 million keys, add a 5th"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Modulo:","marks":[{"type":"bold"}]},{"type":"text","text":" about 800,000 keys move (4/5 of them), and the cache hit rate collapses."}]},{"type":"paragraph","content":[{"type":"text","text":"Ring:","marks":[{"type":"bold"}]},{"type":"text","text":" about 200,000 keys move (1/5), all taken from one neighbour."}]},{"type":"paragraph","content":[{"type":"text","text":"Ring with virtual nodes:","marks":[{"type":"bold"}]},{"type":"text","text":" still about 200,000 keys, but about 50,000 come from each of the four old servers, so the load stays even."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-7i","frameId":"consistent-hashing-frame-73"},"content":[{"type":"text","text":"Virtual nodes"}]},{"type":"paragraph","content":[{"type":"text","text":"With only one position per server, the ring is rarely fair. "},{"type":"text","text":"Virtual nodes","marks":[{"type":"bold"}]},{"type":"text","text":" are the standard fix."}],"attrs":{"blockId":"consistent-hashing-b-74"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-75"},"content":[{"type":"text","text":"The problem: uneven arcs"}]},{"type":"paragraph","content":[{"type":"text","text":"Servers land at random positions, so the arcs between them have very different lengths. One unlucky server can own half the ring."}],"attrs":{"blockId":"consistent-hashing-b-76"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-77"},"content":[{"type":"text","text":"The fix: many positions per server"}]},{"type":"paragraph","content":[{"type":"text","text":"Give each physical server "},{"type":"text","text":"many","marks":[{"type":"bold"}]},{"type":"text","text":" positions on the ring, for example "},{"type":"text","text":"hash(\"A#1\")","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"hash(\"A#2\")","marks":[{"type":"code"}]},{"type":"text","text":" … "},{"type":"text","text":"hash(\"A#200\")","marks":[{"type":"code"}]},{"type":"text","text":". Each position is a "},{"type":"text","text":"virtual node","marks":[{"type":"bold"}]},{"type":"text","text":" (vnode)."}],"attrs":{"blockId":"consistent-hashing-b-78"}},{"type":"paragraph","content":[{"type":"text","text":"Many small arcs average out, so every server ends up with close to its fair share of keys."}],"attrs":{"blockId":"consistent-hashing-b-79"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-7a"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"Left:","marks":[{"type":"bold"}]},{"type":"text","text":" with one position each, A owns the long teal arc, which is "},{"type":"text","text":"69%","marks":[{"type":"bold"}]},{"type":"text","text":" of the keys. B gets only 14% and C 17%."}],"attrs":{"blockId":"consistent-hashing-b-7b"}},{"type":"paragraph","content":[{"type":"text","text":"Right:","marks":[{"type":"bold"}]},{"type":"text","text":" each server has "},{"type":"text","text":"3 virtual nodes","marks":[{"type":"bold"}]},{"type":"text","text":" (A1–A3, B1–B3, C1–C3) spread around the ring, and each server gets about "},{"type":"text","text":"33%","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-7c"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-7d"},"content":[{"type":"text","text":"Why it matters"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Even load:","marks":[{"type":"bold"}]},{"type":"text","text":" the spread between servers shrinks roughly like 1/√V, where V is the number of vnodes per server."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Smooth scaling:","marks":[{"type":"bold"}]},{"type":"text","text":" a new server takes a small slice from "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" other server, not just from one neighbour."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Graceful failure:","marks":[{"type":"bold"}]},{"type":"text","text":" a failed server''s load spreads over all the survivors."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Different machine sizes:","marks":[{"type":"bold"}]},{"type":"text","text":" a bigger machine simply gets more vnodes (weighting)."}]}]}],"attrs":{"blockId":"consistent-hashing-b-7e"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-7f"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"How uneven is it without virtual nodes?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"With one random position per server, the largest arc is about "},{"type":"text","text":"(ln N)/N","marks":[{"type":"bold"}]},{"type":"text","text":" of the ring, roughly ln N times the fair share. With 10 servers, the busiest one typically gets more than twice the average load."}]},{"type":"paragraph","content":[{"type":"text","text":"With 100–200 vnodes per server, the busiest server is usually within about 10% of the average."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The cost is small: the lookup table grows to N × V entries (100 servers × 200 vnodes = 20,000 numbers), and rebalancing moves many small ranges instead of one big one."}],"attrs":{"blockId":"consistent-hashing-b-7g"}},{"type":"paragraph","content":[{"type":"text","text":"Cassandra used 256 vnodes per node for years, then lowered the default to 16 together with a smarter token-allocation algorithm."}],"attrs":{"blockId":"consistent-hashing-b-7h"}},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-9p","frameId":"consistent-hashing-frame-9a"},"content":[{"type":"text","text":"Implementation"}]},{"type":"paragraph","content":[{"type":"text","text":"In code there is no circle. The ring is just a "},{"type":"text","text":"sorted array of positions","marks":[{"type":"bold"}]},{"type":"text","text":" (called "},{"type":"text","text":"tokens","marks":[{"type":"italic"}]},{"type":"text","text":"), each pointing to the server that owns it."}],"attrs":{"blockId":"consistent-hashing-b-9b"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-9c"},"content":[{"type":"text","text":"How a lookup works"}]},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hash the key."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary-search the sorted tokens for the "},{"type":"text","text":"first token ≥ the hash","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"If the hash is larger than every token, "},{"type":"text","text":"wrap around","marks":[{"type":"bold"}]},{"type":"text","text":" to index 0."}]}]}],"attrs":{"blockId":"consistent-hashing-b-9d"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-9e"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"The top row is the sorted token array: 12 (A), 87 (C), 140 (B), 201 (A), 255 (B) and 310 (C)."}],"attrs":{"blockId":"consistent-hashing-b-9f"}},{"type":"paragraph","content":[{"type":"text","text":"A key that hashes to "},{"type":"text","text":"150","marks":[{"type":"bold"}]},{"type":"text","text":" finds 201 as the first token ≥ 150, so it belongs to "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-9g"}},{"type":"paragraph","content":[{"type":"text","text":"A key that hashes to "},{"type":"text","text":"330","marks":[{"type":"bold"}]},{"type":"text","text":" is past the last token, so the search wraps to index 0, token 12, which is also "},{"type":"text","text":"A","marks":[{"type":"bold"}]},{"type":"text","text":" (the dashed red arrow)."}],"attrs":{"blockId":"consistent-hashing-b-9h"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-9i"},"content":[{"type":"text","text":"The code"}]},{"type":"paragraph","content":[{"type":"text","text":"Here is a complete ring with virtual nodes in Python. "},{"type":"text","text":"add()","marks":[{"type":"code"}]},{"type":"text","text":" inserts a server''s vnodes, "},{"type":"text","text":"remove()","marks":[{"type":"code"}]},{"type":"text","text":" takes them out, and "},{"type":"text","text":"get()","marks":[{"type":"code"}]},{"type":"text","text":" is the lookup described above."}],"attrs":{"blockId":"consistent-hashing-b-9j"}},{"type":"codeBlock","attrs":{"language":"python","blockId":"consistent-hashing-b-9k"},"content":[{"type":"text","text":"import bisect\nimport hashlib\n\n\ndef h(s: str) -> int:\n    \"\"\"Stable 64-bit hash: same result on every machine and in every process.\"\"\"\n    return int.from_bytes(hashlib.md5(s.encode()).digest()[:8], \"big\")\n\n\nclass HashRing:\n    def __init__(self, vnodes: int = 100):\n        self.vnodes = vnodes\n        self.tokens: list[int] = []        # sorted ring positions\n        self.owner: dict[int, str] = {}    # position -> server\n\n    def add(self, server: str) -> None:\n        for i in range(self.vnodes):\n            t = h(f\"{server}#{i}\")\n            bisect.insort(self.tokens, t)\n            self.owner[t] = server\n\n    def remove(self, server: str) -> None:\n        for i in range(self.vnodes):\n            t = h(f\"{server}#{i}\")\n            self.tokens.remove(t)\n            del self.owner[t]\n\n    def get(self, key: str) -> str:\n        if not self.tokens:\n            raise LookupError(\"no servers\")\n        i = bisect.bisect_left(self.tokens, h(key))\n        return self.owner[self.tokens[i % len(self.tokens)]]   # wrap around\n\n\nring = HashRing()\nfor s in (\"cache-a\", \"cache-b\", \"cache-c\"):\n    ring.add(s)\nprint(ring.get(\"user:42\"))"}]},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-9l"},"content":[{"type":"text","text":"Cost"}]},{"type":"paragraph","content":[{"type":"text","text":"The blue box at the bottom of the drawing sums up the cost of each operation:"}],"attrs":{"blockId":"consistent-hashing-b-9m"}},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Operation"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Notes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Binary search over N servers × V vnodes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Add / remove a server"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(V · log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Plus moving ~K/N keys of data"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N·V)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"100 servers × 200 vnodes = 20,000 entries"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-9n"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-9o"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Production notes"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Rebuild, don''t mutate.","marks":[{"type":"bold"}]},{"type":"text","text":" Build a new sorted array on each membership change and swap it in atomically, so lookups never take a lock."}]},{"type":"paragraph","content":[{"type":"text","text":"Agree on membership.","marks":[{"type":"bold"}]},{"type":"text","text":" The server list comes from a coordination service (ZooKeeper, etcd, Consul) or a gossip protocol (Cassandra, Dynamo). Clients with different lists disagree about owners."}]},{"type":"paragraph","content":[{"type":"text","text":"Token collisions","marks":[{"type":"bold"}]},{"type":"text","text":" between two servers are astronomically rare with 64-bit hashes. Break ties by server id if you want to be strict."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-ar","frameId":"consistent-hashing-frame-ae"},"content":[{"type":"text","text":"Replication"}]},{"type":"paragraph","content":[{"type":"text","text":"Servers fail, so important data is stored on "},{"type":"text","text":"more than one server","marks":[{"type":"bold"}]},{"type":"text","text":". The ring tells us which ones."}],"attrs":{"blockId":"consistent-hashing-b-af"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-ag"},"content":[{"type":"text","text":"The preference list"}]},{"type":"paragraph","content":[{"type":"text","text":"With a replication factor of 3, a key lives on its "},{"type":"text","text":"owner","marks":[{"type":"bold"}]},{"type":"text","text":" plus the "},{"type":"text","text":"next 2 distinct physical servers","marks":[{"type":"bold"}]},{"type":"text","text":" clockwise. Amazon''s Dynamo calls this list the key''s "},{"type":"text","text":"preference list","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-ah"}},{"type":"paragraph","content":[{"type":"text","text":"With virtual nodes you must "},{"type":"text","text":"skip positions that belong to a server already in the list","marks":[{"type":"bold"}]},{"type":"text","text":". Otherwise two \"replicas\" could end up on the same machine, and one crash would lose both."}],"attrs":{"blockId":"consistent-hashing-b-ai"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-aj"},"content":[{"type":"text","text":"In the drawing"}]},{"type":"paragraph","content":[{"type":"text","text":"Key "},{"type":"text","text":"k","marks":[{"type":"bold"}]},{"type":"text","text":" sits between A and B. Walking clockwise, the arrows mark the replicas in order: "},{"type":"text","text":"1 = B","marks":[{"type":"bold"}]},{"type":"text","text":" (the owner), "},{"type":"text","text":"2 = C","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"3 = D","marks":[{"type":"bold"}]},{"type":"text","text":". Its preference list is B → C → D."}],"attrs":{"blockId":"consistent-hashing-b-ak"}},{"type":"paragraph","content":[{"type":"text","text":"The red box shows what happens when "},{"type":"text","text":"C is down","marks":[{"type":"bold"}]},{"type":"text","text":": the write goes to the next healthy server, "},{"type":"text","text":"E","marks":[{"type":"bold"}]},{"type":"text","text":", which keeps it with a "},{"type":"text","text":"hint","marks":[{"type":"italic"}]},{"type":"text","text":" and hands it back when C returns."}],"attrs":{"blockId":"consistent-hashing-b-al"}},{"type":"callout","attrs":{"tone":"red","blockId":"consistent-hashing-b-am"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Replication factor 3 survives losing any 2 of the 3 servers, but only if they are really different machines, ideally in different racks or availability zones."}]}]},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-an"},"content":[{"type":"text","text":"Quorums"}]},{"type":"paragraph","content":[{"type":"text","text":"With "},{"type":"text","text":"N","marks":[{"type":"bold"}]},{"type":"text","text":" replicas, a write waits for "},{"type":"text","text":"W","marks":[{"type":"bold"}]},{"type":"text","text":" acknowledgements and a read asks "},{"type":"text","text":"R","marks":[{"type":"bold"}]},{"type":"text","text":" replicas."}],"attrs":{"blockId":"consistent-hashing-b-ao"}},{"type":"paragraph","content":[{"type":"text","text":"If "},{"type":"text","text":"R + W > N","marks":[{"type":"bold"}]},{"type":"text","text":", every read overlaps the latest write, so reads see the newest value. The drawing uses N = 3, W = 2, R = 2. Lowering W or R trades consistency for speed and availability."}],"attrs":{"blockId":"consistent-hashing-b-ap"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-aq"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Sloppy quorum, hinted handoff and zones"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Writing to the next healthy server while a replica is down is called a "},{"type":"text","text":"sloppy quorum","marks":[{"type":"bold"}]},{"type":"text","text":". Handing the data back later is "},{"type":"text","text":"hinted handoff","marks":[{"type":"bold"}]},{"type":"text","text":". Together they keep writes succeeding during short outages."}]},{"type":"paragraph","content":[{"type":"text","text":"Rack and zone awareness (e.g. Cassandra''s NetworkTopologyStrategy) keeps walking the ring until the replicas are in different racks or zones."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-c1","frameId":"consistent-hashing-frame-bm"},"content":[{"type":"text","text":"Hot keys and uneven load"}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing balances "},{"type":"text","text":"keys","marks":[{"type":"bold"}]},{"type":"text","text":", not "},{"type":"text","text":"traffic","marks":[{"type":"bold"}]},{"type":"text","text":". One very popular key, such as a celebrity''s profile or a viral post, still lives on one server and can overload it."}],"attrs":{"blockId":"consistent-hashing-b-bn"}},{"type":"paragraph","content":[{"type":"text","text":"There are four common fixes. The drawing shows them in the same order as below."}],"attrs":{"blockId":"consistent-hashing-b-bo"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-bp"},"content":[{"type":"text","text":"1. Bounded loads"}]},{"type":"paragraph","content":[{"type":"text","text":"Cap every server at "},{"type":"text","text":"(1+ε) × the average load","marks":[{"type":"bold"}]},{"type":"text","text":". If a key''s owner is already full, keep walking clockwise to the next server that has room."}],"attrs":{"blockId":"consistent-hashing-b-bq"}},{"type":"paragraph","content":[{"type":"text","text":"In the drawing:","marks":[{"type":"bold"}]},{"type":"text","text":" server "},{"type":"text","text":"B","marks":[{"type":"bold"}]},{"type":"text","text":" has reached the dashed "},{"type":"text","text":"cap","marks":[{"type":"bold"}]},{"type":"text","text":" line, so the next key goes on to "},{"type":"text","text":"C","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-br"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-bs"},"content":[{"type":"text","text":"2. Hot-key splitting"}]},{"type":"paragraph","content":[{"type":"text","text":"Store the hot key as several copies, "},{"type":"text","text":"key#1 … key#k","marks":[{"type":"code"}]},{"type":"text","text":", on different servers, and read a random copy."}],"attrs":{"blockId":"consistent-hashing-b-bt"}},{"type":"paragraph","content":[{"type":"text","text":"In the drawing:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"celebrity:1","marks":[{"type":"code"}]},{"type":"text","text":" is split into "},{"type":"text","text":"#1, #2 and #3","marks":[{"type":"bold"}]},{"type":"text","text":" on three servers, which share its reads."}],"attrs":{"blockId":"consistent-hashing-b-bu"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-bv"},"content":[{"type":"text","text":"3. Weights"}]},{"type":"paragraph","content":[{"type":"text","text":"Give bigger machines more vnodes, so they own a bigger share of the ring (the blue box)."}],"attrs":{"blockId":"consistent-hashing-b-bw"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-bx"},"content":[{"type":"text","text":"4. Near cache"}]},{"type":"paragraph","content":[{"type":"text","text":"Keep the hottest keys in the client or proxy memory for a few seconds, so most reads never reach the server (the green box)."}],"attrs":{"blockId":"consistent-hashing-b-by"}},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Technique"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Helps with"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Trade-off"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Bounded loads"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any overloaded server"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"A few keys move as load shifts"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot-key splitting"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One extremely hot key"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Every write must update all copies"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Weights"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Machines of different sizes"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Static: doesn''t react to traffic"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Near cache"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Read-heavy hot keys"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Slightly stale reads"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-bz"}},{"type":"details","attrs":{"tone":"sky","blockId":"consistent-hashing-b-c0"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Where bounded loads come from"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Proposed by Mirrokni, Thorup and Zadimoghaddam (Google, 2017). Each server accepts at most ⌈(1+ε) · average⌉ requests."}]},{"type":"paragraph","content":[{"type":"text","text":"It keeps most of consistent hashing''s stability while guaranteeing that no server is overloaded. Vimeo used it for video caching, and HAProxy supports it as "},{"type":"text","text":"hash-balance-factor","marks":[{"type":"code"}]},{"type":"text","text":"."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-dc","frameId":"consistent-hashing-frame-cv"},"content":[{"type":"text","text":"Alternatives"}]},{"type":"paragraph","content":[{"type":"text","text":"The ring with virtual nodes is not the only way to move few keys when servers change. Each card in the drawing is one alternative, in the same order as below."}],"attrs":{"blockId":"consistent-hashing-b-cw"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-cx"},"content":[{"type":"text","text":"Ring + virtual nodes"}]},{"type":"paragraph","content":[{"type":"text","text":"Everything described so far: binary search on a ring, and any server can join or leave at any time. It is the default for caches and storage clusters (Cassandra, Dynamo)."}],"attrs":{"blockId":"consistent-hashing-b-cy"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-cz"},"content":[{"type":"text","text":"Rendezvous hashing (HRW)"}]},{"type":"paragraph","content":[{"type":"text","text":"For each key, compute "},{"type":"text","text":"score = hash(key, server)","marks":[{"type":"code"}]},{"type":"text","text":" for "},{"type":"text","text":"every","marks":[{"type":"bold"}]},{"type":"text","text":" server and pick the highest. There is no ring and there are no vnodes."}],"attrs":{"blockId":"consistent-hashing-b-d0"}},{"type":"paragraph","content":[{"type":"text","text":"When a server leaves, only its keys move, each to its second-best server. Lookups cost O(N), so it suits small server sets."}],"attrs":{"blockId":"consistent-hashing-b-d1"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-d2"},"content":[{"type":"text","text":"Jump consistent hash"}]},{"type":"paragraph","content":[{"type":"text","text":"A five-line function from Google (2014) that maps a key to bucket 0…n−1 with "},{"type":"text","text":"perfect balance and no memory","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"consistent-hashing-b-d3"}},{"type":"paragraph","content":[{"type":"text","text":"Its limitation: buckets are numbered, so you can only add or remove the "},{"type":"text","text":"last","marks":[{"type":"bold"}]},{"type":"text","text":" one. That fits numbered storage shards, not random server failures."}],"attrs":{"blockId":"consistent-hashing-b-d4"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-d5"},"content":[{"type":"text","text":"Maglev hashing"}]},{"type":"paragraph","content":[{"type":"text","text":"Google''s load balancer builds a "},{"type":"text","text":"fixed-size lookup table","marks":[{"type":"bold"}]},{"type":"text","text":" (for example 65,537 entries) for O(1) lookups with near-perfect balance. It is made for routing network packets, where speed matters most."}],"attrs":{"blockId":"consistent-hashing-b-d6"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-d7"},"content":[{"type":"text","text":"Range sharding"}]},{"type":"paragraph","content":[{"type":"text","text":"Instead of hashing, split the key space into "},{"type":"text","text":"ordered ranges","marks":[{"type":"bold"}]},{"type":"text","text":" and move whole ranges between servers. Keys stay sorted, so range scans are fast. Bigtable, HBase and CockroachDB work this way."}],"attrs":{"blockId":"consistent-hashing-b-d8"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-d9"},"content":[{"type":"text","text":"Side by side"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Approach"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Memory"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Balance"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Membership changes"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Best for"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Ring + vnodes"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log(N·V))","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N·V)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Good (more vnodes = better)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any server, any time"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Caches and storage clusters"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Rendezvous (HRW)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Excellent"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any server, any time"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Small server sets (up to ~100)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Jump consistent hash"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log N)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Perfect"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Only the last bucket"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Numbered storage shards"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Maglev"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(1)","marks":[{"type":"code"}]}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Fixed table"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Near perfect"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Any; a few % of keys move"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Packet load balancers"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Range sharding"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"O(log S)","marks":[{"type":"code"}]},{"type":"text","text":" (metadata)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Range table"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Managed by splits"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Move ranges explicitly"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Ordered keys and range scans"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-da"}},{"type":"callout","attrs":{"tone":"mint","blockId":"consistent-hashing-b-db"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Rule of thumb: "},{"type":"text","text":"ring + vnodes","marks":[{"type":"bold"}]},{"type":"text","text":" for dynamic clusters, "},{"type":"text","text":"rendezvous","marks":[{"type":"bold"}]},{"type":"text","text":" for small server sets, "},{"type":"text","text":"jump hash","marks":[{"type":"bold"}]},{"type":"text","text":" for fixed numbered shards, "},{"type":"text","text":"Maglev","marks":[{"type":"bold"}]},{"type":"text","text":" for packet load balancing, and "},{"type":"text","text":"ranges","marks":[{"type":"bold"}]},{"type":"text","text":" when you need ordered scans."}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-e3","frameId":"consistent-hashing-frame-dt"},"content":[{"type":"text","text":"Where it''s used"}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing shows up wherever many machines share data or traffic, and machines come and go."}],"attrs":{"blockId":"consistent-hashing-b-du"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-dv"},"content":[{"type":"text","text":"In the drawing: a cache tier"}]},{"type":"paragraph","content":[{"type":"text","text":"Three "},{"type":"text","text":"clients","marks":[{"type":"bold"}]},{"type":"text","text":" send requests to a "},{"type":"text","text":"router","marks":[{"type":"bold"}]},{"type":"text","text":". The router is either a client library or a proxy, and it holds the ring."}],"attrs":{"blockId":"consistent-hashing-b-dw"}},{"type":"paragraph","content":[{"type":"text","text":"For each key, the router uses the ring to pick one of the caches, "},{"type":"text","text":"A to D","marks":[{"type":"bold"}]},{"type":"text","text":". On a miss, that cache reads from the "},{"type":"text","text":"database","marks":[{"type":"bold"}]},{"type":"text","text":" and keeps the result."}],"attrs":{"blockId":"consistent-hashing-b-dx"}},{"type":"paragraph","content":[{"type":"text","text":"When a cache is added or removed, only the keys in one arc change cache, so the database never sees a stampede."}],"attrs":{"blockId":"consistent-hashing-b-dy"}},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-dz"},"content":[{"type":"text","text":"Real systems"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"System"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"How it uses consistent hashing"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Amazon Dynamo / DynamoDB"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Partitions items over storage nodes on a ring; preference lists for replication"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Apache Cassandra / ScyllaDB"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Token ring with vnodes; replicas are the next nodes on the ring (rack and data-centre aware)"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Memcached clients (ketama)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"The client library picks the cache server; no central router"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Nginx, Envoy, HAProxy"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"hash … consistent","marks":[{"type":"code"}]},{"type":"text","text":", ring-hash or Maglev load balancing keeps a user on the same backend"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Akamai and other CDNs"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Decide which edge server caches which URL"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Chat and gaming backends (e.g. Discord)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Route all events of one channel, room or user to the same process"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-e0"}},{"type":"callout","attrs":{"tone":"red","blockId":"consistent-hashing-b-e1"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Interview trap: "},{"type":"text","text":"Redis Cluster does not use a hash ring.","marks":[{"type":"bold"}]},{"type":"text","text":" It uses "},{"type":"text","text":"16,384 fixed hash slots","marks":[{"type":"bold"}]},{"type":"text","text":" ("},{"type":"text","text":"CRC16(key) mod 16384","marks":[{"type":"code"}]},{"type":"text","text":") assigned to nodes, and moves whole slots when the cluster changes. Same goal, different mechanism."}]}]},{"type":"paragraph","content":[{"type":"text","text":"Where the ring lives varies: "},{"type":"text","text":"in the client library","marks":[{"type":"bold"}]},{"type":"text","text":" (ketama, token-aware Cassandra drivers), "},{"type":"text","text":"in a proxy","marks":[{"type":"bold"}]},{"type":"text","text":" in front of the caches (twemproxy, mcrouter, Envoy), or "},{"type":"text","text":"inside the database","marks":[{"type":"bold"}]},{"type":"text","text":" itself (Cassandra, Dynamo)."}],"attrs":{"blockId":"consistent-hashing-b-e2"}},{"type":"heading","attrs":{"level":2,"sectionId":"consistent-hashing-s-f8","frameId":"consistent-hashing-frame-f2"},"content":[{"type":"text","text":"Interview cheat sheet"}]},{"type":"paragraph","content":[{"type":"text","text":"In an interview, explain consistent hashing in these "},{"type":"text","text":"eight steps","marks":[{"type":"bold"}]},{"type":"text","text":". Each card in the drawing is one step."}],"attrs":{"blockId":"consistent-hashing-b-f3"}},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Problem:","marks":[{"type":"bold"}]},{"type":"text","text":" "},{"type":"text","text":"hash % N","marks":[{"type":"code"}]},{"type":"text","text":" remaps ~N/(N+1) of keys when N changes, causing a cache stampede."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Ring:","marks":[{"type":"bold"}]},{"type":"text","text":" hash servers and keys onto the same circle (0…2³²−1, wrapping around)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Lookup:","marks":[{"type":"bold"}]},{"type":"text","text":" the first server clockwise; in code, a sorted array plus binary search, O(log(N·V))."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Changes:","marks":[{"type":"bold"}]},{"type":"text","text":" adding or removing a server moves only ~K/N keys, from or to its neighbours."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Virtual nodes:","marks":[{"type":"bold"}]},{"type":"text","text":" 100–256 positions per server for even load, smooth scaling and weights."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Replication:","marks":[{"type":"bold"}]},{"type":"text","text":" the next R−1 distinct physical servers (rack and zone aware); R + W > N for consistency."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot keys:","marks":[{"type":"bold"}]},{"type":"text","text":" balanced keys ≠ balanced traffic, so use bounded loads, key splitting and local caches."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Alternatives:","marks":[{"type":"bold"}]},{"type":"text","text":" rendezvous, jump hash, Maglev and range sharding (and Redis Cluster''s slots)."}]}]}],"attrs":{"blockId":"consistent-hashing-b-f4"}},{"type":"details","attrs":{"tone":"mint","blockId":"consistent-hashing-b-f5"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"The 60-second answer"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Plain modulo hashing reshuffles almost every key when a server is added or removed."}]},{"type":"paragraph","content":[{"type":"text","text":"Consistent hashing puts servers and keys on the same hash ring and gives each key to the next server clockwise, so a change only moves the keys in one arc, about K/N of them."}]},{"type":"paragraph","content":[{"type":"text","text":"Real systems give each server many virtual nodes to even out the load, replicate each key to the next few distinct servers, and handle hot keys separately, because the ring balances keys, not traffic. Dynamo, Cassandra and memcached clients all work this way.\""}]}]}]},{"type":"heading","attrs":{"level":3,"blockId":"consistent-hashing-b-f6"},"content":[{"type":"text","text":"Questions you may get"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Question"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Short answer"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How many keys move when a node joins?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"~K/N (its fair share), from its ring neighbours, or from all nodes with vnodes"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Why virtual nodes?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Even load, smooth scaling, failure spread, weights"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do you find the owner fast?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Sorted token array + binary search; rebuild on membership change"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"How do replicas work?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Next distinct physical nodes clockwise; quorum R + W > N"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One key is extremely hot. Now what?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Bounded loads, split the key, cache it near clients"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Does Redis Cluster use this?"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No: 16,384 hash slots"}]}]}]}],"attrs":{"blockId":"consistent-hashing-b-f7"}}]}'::jsonb, canvas = '{"layout":"40-60","files":{},"elements":[{"id":"consistent-hashing-frame-1","type":"frame","x":0,"y":0,"width":1600,"height":1200,"name":"Why naive hashing breaks","seed":1,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"consistent-hashing-el-h","frameId":"consistent-hashing-frame-1","seed":1835177423,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":244.15999999999997,"y":40,"width":1111.68,"height":57.5,"text":"hash(key) % N: what happens when N changes?","originalText":"hash(key) % N: what happens when N changes?","fontSize":46,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#1e1e1e","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":1,"roundness":null,"lineHeight":1.25,"autoResize":true,"containerId":null},{"id":"consistent-hashing-el-i","frameId":"consistent-hashing-frame-1","seed":1818399804,"roughness":1,"opacity":100,"angle":0,"strokeStyle":"solid","groupIds":[],"type":"text","x":550.48,"y":104,"width":499.04,"height":32.5,"text":"Same 8 keys, 3 servers → 4 servers","originalText":"Same 8 keys, 3 servers → 4 servers","fontSize":26,"fontFamily":5,"textAlign":"center","verticalAlign":"top","strokeColor":"#64748b","backgroundColor":"transparent","fillStyle":"