update public.article_drafts set doc = '{"type":"doc","content":[{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-9","frameId":"telemetry-etl-pipeline-frame-1"},"content":[{"type":"text","text":"The problem"}]},{"type":"paragraph","content":[{"type":"text","text":"Thousands of storage arrays (more than "},{"type":"text","text":"10,000","marks":[{"type":"bold"}]},{"type":"text","text":") keep writing "},{"type":"text","text":"telemetry files","marks":[{"type":"bold"}]},{"type":"text","text":" about their own health: disks, ports, performance counters. Each array has an id called "},{"type":"text","text":"symm_id","marks":[{"type":"code"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-2"}},{"type":"paragraph","content":[{"type":"text","text":"The files land on a shared network drive, the "},{"type":"text","text":"source NAS","marks":[{"type":"bold"}]},{"type":"text","text":". On their own they are just raw files that nobody can query."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-3"}},{"type":"paragraph","content":[{"type":"text","text":"We need a pipeline that turns every file into "},{"type":"text","text":"rows in a database","marks":[{"type":"bold"}]},{"type":"text","text":", so that analytics apps can join and query them."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-4"}},{"type":"paragraph","content":[{"type":"text","text":"It has to be trustworthy. Five promises shape the whole design:"}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5"}},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No file is lost","marks":[{"type":"bold"}]},{"type":"text","text":", even when machines crash."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No file is loaded twice.","marks":[{"type":"bold"}]}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Files from the "},{"type":"text","text":"same array are processed in order","marks":[{"type":"bold"}]},{"type":"text","text":" (a later file can depend on an earlier one)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"corrupt file is set aside","marks":[{"type":"bold"}]},{"type":"text","text":", never allowed to block the rest."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The team can "},{"type":"text","text":"see what is happening","marks":[{"type":"bold"}]},{"type":"text","text":", 24×7."}]}]}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6"}},{"type":"paragraph","content":[{"type":"text","text":"The load is steady rather than huge: about "},{"type":"text","text":"500,000 files a day","marks":[{"type":"bold"}]},{"type":"text","text":", which is "},{"type":"text","text":"~6 files per second","marks":[{"type":"bold"}]},{"type":"text","text":" on average and "},{"type":"text","text":"30–60 per second","marks":[{"type":"bold"}]},{"type":"text","text":" at peak."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-7"}},{"type":"callout","attrs":{"tone":"mint","blockId":"telemetry-etl-pipeline-b-8"},"content":[{"type":"paragraph","content":[{"type":"text","text":"The hard part is not speed. It is "},{"type":"text","text":"correctness under failure","marks":[{"type":"bold"}]},{"type":"text","text":": crashes, retries and bad files must never lose, duplicate or reorder data."}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-1i","frameId":"telemetry-etl-pipeline-frame-19"},"content":[{"type":"text","text":"The big picture"}]},{"type":"paragraph","content":[{"type":"text","text":"Before the details, follow "},{"type":"text","text":"one file","marks":[{"type":"bold"}]},{"type":"text","text":" through the system. Every box in the drawing appears at the moment the file reaches it."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1a"}},{"type":"paragraph","content":[{"type":"text","text":"An array drops a file on the source NAS. The "},{"type":"text","text":"ingestion service","marks":[{"type":"bold"}]},{"type":"text","text":" notices it, makes sure it has not seen it before (using "},{"type":"text","text":"Redis","marks":[{"type":"bold"}]},{"type":"text","text":"), and creates a small task message."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1b"}},{"type":"paragraph","content":[{"type":"text","text":"The task goes into "},{"type":"text","text":"Kafka","marks":[{"type":"bold"}]},{"type":"text","text":", a durable queue. Kafka holds the work until a worker is free, so bursts never overwhelm anyone."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1c"}},{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"parser worker","marks":[{"type":"bold"}]},{"type":"text","text":" takes the task, reads the file, and writes all its rows into "},{"type":"text","text":"PostgreSQL","marks":[{"type":"bold"}]},{"type":"text","text":" in one transaction."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1d"}},{"type":"paragraph","content":[{"type":"text","text":"After the data is safe, the worker asks for the file to be archived. The "},{"type":"text","text":"archival service","marks":[{"type":"bold"}]},{"type":"text","text":" compresses it into the "},{"type":"text","text":"archive NAS","marks":[{"type":"bold"}]},{"type":"text","text":" and only then removes the original."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1e"}},{"type":"paragraph","content":[{"type":"text","text":"If the file is corrupt, it goes to the "},{"type":"text","text":"quarantine store","marks":[{"type":"bold"}]},{"type":"text","text":" instead, with the reason, for a human to look at."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1f"}},{"type":"paragraph","content":[{"type":"text","text":"All along the way, every service sends logs and metrics to the "},{"type":"text","text":"observability","marks":[{"type":"bold"}]},{"type":"text","text":" stack, tagged with the file''s "},{"type":"text","text":"task_id","marks":[{"type":"code"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-1g"}},{"type":"callout","attrs":{"tone":"sky","blockId":"telemetry-etl-pipeline-b-1h"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Notice the pattern: services never call each other directly. They "},{"type":"text","text":"talk through Kafka topics","marks":[{"type":"bold"}]},{"type":"text","text":", so each one can slow down, crash or scale without breaking the others."}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-36","frameId":"telemetry-etl-pipeline-frame-2w"},"content":[{"type":"text","text":"Finding new files"}]},{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"ingestion service","marks":[{"type":"bold"}]},{"type":"text","text":" is the front door. Its only job is to notice new files and turn each one into a task, exactly once."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-2x"}},{"type":"paragraph","content":[{"type":"text","text":"Every 30 seconds it scans the NAS folders. From each file''s name it reads the array ("},{"type":"text","text":"symm_id","marks":[{"type":"code"}]},{"type":"text","text":") and the time the file was made."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-2y"}},{"type":"paragraph","content":[{"type":"text","text":"Then it computes a checksum (a fingerprint of the file''s bytes) and asks "},{"type":"text","text":"Redis","marks":[{"type":"bold"}]},{"type":"text","text":": "},{"type":"text","text":"have I seen this fingerprint before?","marks":[{"type":"italic"}]},{"type":"text","text":" If yes, the file is skipped."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-2z"}},{"type":"paragraph","content":[{"type":"text","text":"If the file is new, it publishes a "},{"type":"text","text":"TaskMessage","marks":[{"type":"code"}]},{"type":"text","text":" to Kafka, "},{"type":"text","text":"keyed by `symm_id`","marks":[{"type":"bold"}]},{"type":"text","text":" (the next split shows why the key matters), and marks the file as "},{"type":"text","text":"queued","marks":[{"type":"italic"}]},{"type":"text","text":" in Redis."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-30"}},{"type":"paragraph","content":[{"type":"text","text":"If Kafka is unreachable, it simply retries later. The file stays on the NAS, and "},{"type":"text","text":"the NAS is the source of truth","marks":[{"type":"bold"}]},{"type":"text","text":", so nothing can be lost."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-31"}},{"type":"paragraph","content":[{"type":"text","text":"Trade-off: where should the \"seen files\" list live? We looked at four places:"}],"attrs":{"blockId":"telemetry-etl-pipeline-b-32"}},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Option"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Good"}]}]},{"type":"tableHeader","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Redis","marks":[{"type":"bold"}]},{"type":"text","text":" (chosen)"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Shared by all ingestion instances, sub-millisecond, entries expire on their own"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"One more cluster to run"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Move file to a "},{"type":"text","text":"queued/","marks":[{"type":"code"}]},{"type":"text","text":" folder"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No extra infrastructure"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Needs rename rights on the NAS"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL table"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Reuses what we already have"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Extra reads on the busiest component"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Local SQLite"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"No network at all"}]}]},{"type":"tableCell","content":[{"type":"paragraph","content":[{"type":"text","text":"Not shared; lost on restart"}]}]}]}],"attrs":{"blockId":"telemetry-etl-pipeline-b-33"}},{"type":"paragraph","content":[{"type":"text","text":"Redis won because several ingestion instances run in parallel and must share one memory of what they have seen."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-34"}},{"type":"paragraph","content":[{"type":"text","text":"And if Redis ever misses (say, during a failover), the database''s own duplicate check catches it. Dedup here is an "},{"type":"text","text":"optimisation","marks":[{"type":"bold"}]},{"type":"text","text":", not the last line of defence."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-35"}},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-4c","frameId":"telemetry-etl-pipeline-frame-43"},"content":[{"type":"text","text":"Kafka: order without a bottleneck"}]},{"type":"paragraph","content":[{"type":"text","text":"Kafka sits between ingestion and the workers. It solves two problems at once: "},{"type":"text","text":"ordering","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"sharing the work","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-44"}},{"type":"paragraph","content":[{"type":"text","text":"Kafka splits a topic into "},{"type":"text","text":"partitions","marks":[{"type":"bold"}]},{"type":"text","text":": independent lanes. Messages inside one lane are kept in order; different lanes move in parallel."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-45"}},{"type":"paragraph","content":[{"type":"text","text":"Every message is keyed by "},{"type":"text","text":"symm_id","marks":[{"type":"code"}]},{"type":"text","text":", and the same key always goes to the same partition. So "},{"type":"text","text":"all files from one array travel in one lane, in order","marks":[{"type":"bold"}]},{"type":"text","text":", while different arrays share the other lanes."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-46"}},{"type":"paragraph","content":[{"type":"text","text":"Parser workers form a "},{"type":"text","text":"consumer group","marks":[{"type":"bold"}]},{"type":"text","text":": Kafka gives each partition to exactly one worker at a time. If a worker joins or dies, Kafka hands its partitions to the others automatically."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-47"}},{"type":"paragraph","content":[{"type":"text","text":"A worker tells Kafka \"done\" (commits the offset) "},{"type":"text","text":"only after the database commit","marks":[{"type":"bold"}]},{"type":"text","text":". If it crashes halfway, the same message is delivered again, so work is never lost."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-48"}},{"type":"paragraph","content":[{"type":"text","text":"If workers fall behind, messages simply wait in Kafka. The queue absorbs bursts, and the growing "},{"type":"text","text":"consumer lag","marks":[{"type":"bold"}]},{"type":"text","text":" is the signal to add workers."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-49"}},{"type":"callout","attrs":{"tone":"sand","blockId":"telemetry-etl-pipeline-b-4a"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Trade-off:","marks":[{"type":"bold"}]},{"type":"text","text":" one partition is read by one worker, so the number of partitions is the ceiling on parallel workers. We created more partitions than we needed on day one, because adding them later reshuffles which array goes to which lane."}]}]},{"type":"details","attrs":{"tone":"sky","blockId":"telemetry-etl-pipeline-b-4b"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Why not one global order across all files?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Different arrays are independent; nothing in array A depends on array B."}]},{"type":"paragraph","content":[{"type":"text","text":"A single global order would force one worker to do everything. Ordering "},{"type":"text","text":"per array","marks":[{"type":"bold"}]},{"type":"text","text":" keeps the guarantee that matters and lets the rest run in parallel."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-5w","frameId":"telemetry-etl-pipeline-frame-5o"},"content":[{"type":"text","text":"Parser workers"}]},{"type":"paragraph","content":[{"type":"text","text":"The workers do the real work: turn a raw file into rows. They are "},{"type":"text","text":"stateless","marks":[{"type":"bold"}]},{"type":"text","text":": everything they need is in Kafka (which task is next) and PostgreSQL (the data), so any worker can take over any partition."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5p"}},{"type":"paragraph","content":[{"type":"text","text":"A worker takes a task from Kafka and fetches the file from the NAS."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5q"}},{"type":"paragraph","content":[{"type":"text","text":"First it checks the fingerprint. If the bytes do not match what ingestion saw, the file was damaged on the way (a partial write, a bad disk): it goes straight to "},{"type":"text","text":"quarantine","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5r"}},{"type":"paragraph","content":[{"type":"text","text":"Then it parses the file into typed records. A malformed file also goes to quarantine. Retrying a corrupt file would fail the same way forever and "},{"type":"text","text":"block the whole lane","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5s"}},{"type":"paragraph","content":[{"type":"text","text":"All rows from the file are written to PostgreSQL in "},{"type":"text","text":"one transaction","marks":[{"type":"bold"}]},{"type":"text","text":". If the database has a hiccup (timeout, deadlock), the worker retries up to 3 times, then gives the task to a "},{"type":"text","text":"dead-letter queue (DLQ)","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5t"}},{"type":"paragraph","content":[{"type":"text","text":"Only after the commit does it publish an archival request and commit the Kafka offset. Every path, success or failure, ends with that commit, so the lane keeps moving."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-5u"}},{"type":"details","attrs":{"tone":"sky","blockId":"telemetry-etl-pipeline-b-5v"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"Trade-off: why not a separate \"DB loader\" service?"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Splitting parse and load would need another topic, serialising parsed data, and a harder rollback story."}]},{"type":"paragraph","content":[{"type":"text","text":"Inline loading keeps it "},{"type":"text","text":"atomic, simpler and one network hop shorter","marks":[{"type":"bold"}]},{"type":"text","text":". At ~6 files per second, parsing and loading never bottleneck separately, so adding workers scales both together."}]},{"type":"paragraph","content":[{"type":"text","text":"A separate loader would only pay off if parsing were CPU-heavy and loading I/O-heavy with very different scaling needs."}]}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-73","frameId":"telemetry-etl-pipeline-frame-6u"},"content":[{"type":"text","text":"The database"}]},{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL was chosen for "},{"type":"text","text":"ACID transactions","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"rich joins","marks":[{"type":"bold"}]},{"type":"text","text":": analytics apps combine array, disk and port data in one query."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6v"}},{"type":"paragraph","content":[{"type":"text","text":"Each file becomes rows in several related tables ("},{"type":"text","text":"array_metrics","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"disk_stats","marks":[{"type":"code"}]},{"type":"text","text":", "},{"type":"text","text":"port_stats","marks":[{"type":"code"}]},{"type":"text","text":"), linked by "},{"type":"text","text":"symm_id","marks":[{"type":"code"}]},{"type":"text","text":" + file time. They are written between one "},{"type":"text","text":"BEGIN","marks":[{"type":"code"}]},{"type":"text","text":" and one "},{"type":"text","text":"COMMIT","marks":[{"type":"code"}]},{"type":"text","text":": all of them, or none."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6w"}},{"type":"paragraph","content":[{"type":"text","text":"Before inserting, the worker checks a small "},{"type":"text","text":"processed_files","marks":[{"type":"code"}]},{"type":"text","text":" table for this file''s (array, time, fingerprint). If it is there, the file is skipped; if not, the data and the "},{"type":"text","text":"processed_files","marks":[{"type":"code"}]},{"type":"text","text":" row are committed "},{"type":"text","text":"together","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6x"}},{"type":"paragraph","content":[{"type":"text","text":"This is what makes Kafka''s redeliveries safe. Kafka promises "},{"type":"text","text":"at least once","marks":[{"type":"bold"}]},{"type":"text","text":"; the database turns that into "},{"type":"text","text":"effectively once","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6y"}},{"type":"paragraph","content":[{"type":"text","text":"Writes never stop, so we scaled in layers and stopped at the first one that was enough:"}],"attrs":{"blockId":"telemetry-etl-pipeline-b-6z"}},{"type":"orderedList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tune","marks":[{"type":"bold"}]},{"type":"text","text":": one multi-row insert per file, WAL settings for heavy writes, and "},{"type":"text","text":"PgBouncer","marks":[{"type":"bold"}]},{"type":"text","text":" so N workers share a few connections."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Read replicas","marks":[{"type":"bold"}]},{"type":"text","text":": analytics queries go to replicas, keeping the primary for writes."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Monthly partitions","marks":[{"type":"bold"}]},{"type":"text","text":": new writes always hit a small, hot partition; old months become read-only."}]}]}],"attrs":{"blockId":"telemetry-etl-pipeline-b-70"}},{"type":"paragraph","content":[{"type":"text","text":"Sharding by "},{"type":"text","text":"symm_id","marks":[{"type":"code"}]},{"type":"text","text":" is the escape hatch we deliberately did "},{"type":"text","text":"not","marks":[{"type":"bold"}]},{"type":"text","text":" take. At ~60 writes per second at peak we use about "},{"type":"text","text":"1%","marks":[{"type":"bold"}]},{"type":"text","text":" of what one tuned primary handles (5K–10K TPS). Sharding would add routing and break cross-shard joins for no gain."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-71"}},{"type":"callout","attrs":{"tone":"mint","blockId":"telemetry-etl-pipeline-b-72"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Design rule: "},{"type":"text","text":"pick the simplest setup that has headroom","marks":[{"type":"bold"}]},{"type":"text","text":", and write down what would make you change it (here: 100× more arrays)."}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-85","frameId":"telemetry-etl-pipeline-frame-7x"},"content":[{"type":"text","text":"Archiving safely"}]},{"type":"paragraph","content":[{"type":"text","text":"Once a file is safely in the database, it should leave the busy source NAS, but it must never just vanish. The "},{"type":"text","text":"archival service","marks":[{"type":"bold"}]},{"type":"text","text":" reads the original, compresses it with "},{"type":"text","text":"zstd","marks":[{"type":"bold"}]},{"type":"text","text":" (smaller than gzip at a similar speed) and writes it to the "},{"type":"text","text":"archive NAS","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-7y"}},{"type":"paragraph","content":[{"type":"text","text":"Then it reads the archived copy back and checks its fingerprint. If anything is wrong it retries with backoff, and the original stays where it is."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-7z"}},{"type":"paragraph","content":[{"type":"text","text":"Only after a verified archive does it delete the original and record the archive path in "},{"type":"text","text":"processed_files","marks":[{"type":"code"}]},{"type":"text","text":". The order is the whole point: the worst case is "},{"type":"text","text":"two copies, never zero","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-80"}},{"type":"paragraph","content":[{"type":"text","text":"Archives follow one path pattern, so finding a file later needs no search:"}],"attrs":{"blockId":"telemetry-etl-pipeline-b-81"}},{"type":"paragraph","content":[{"type":"text","text":"archive/{symm_id}/{YYYY-MM-DD}/{file}.zst","marks":[{"type":"code"}]}],"attrs":{"blockId":"telemetry-etl-pipeline-b-82"}},{"type":"paragraph","content":[{"type":"text","text":"Why a separate service and not part of the worker? Compression and NAS writes are slow and can wait. Keeping them apart means "},{"type":"text","text":"parsing never waits for archiving","marks":[{"type":"bold"}]},{"type":"text","text":", and a backlog of archiving work never delays fresh data."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-83"}},{"type":"paragraph","content":[{"type":"text","text":"Archives are kept for a configurable period (for example 90 days), and a daily cleanup job removes older ones."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-84"}},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-98","frameId":"telemetry-etl-pipeline-frame-8x"},"content":[{"type":"text","text":"When things go wrong"}]},{"type":"paragraph","content":[{"type":"text","text":"In a system that runs 24×7, failure is normal. The design sorts every failure into one of four kinds, and each kind has exactly one response."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-8y"}},{"type":"paragraph","content":[{"type":"text","text":"Transient failures (a database timeout, the NAS or a Kafka broker briefly down) are retried with exponential backoff. After the maximum retries the task moves to the "},{"type":"text","text":"DLQ","marks":[{"type":"bold"}]},{"type":"text","text":"."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-8z"}},{"type":"paragraph","content":[{"type":"text","text":"Corrupt files (bad fingerprint, malformed content) are quarantined immediately: the file goes to a quarantine folder and the reason goes into a table. "},{"type":"text","text":"Never retried","marks":[{"type":"bold"}]},{"type":"text","text":", because it would fail the same way."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-90"}},{"type":"paragraph","content":[{"type":"text","text":"Persistent failures (a schema mismatch, an unknown file format) also end in the DLQ. Each DLQ message carries the original task and its failure history, so after fixing the cause an engineer can "},{"type":"text","text":"replay","marks":[{"type":"bold"}]},{"type":"text","text":" it."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-91"}},{"type":"paragraph","content":[{"type":"text","text":"Crashes (a worker dies, runs out of memory) need no code at all: Kafka notices and redelivers the unfinished message to another worker."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-92"}},{"type":"paragraph","content":[{"type":"text","text":"Seeing all this needs three kinds of signals. Logs: every service writes structured logs to a Kafka topic; Logstash indexes them into Elasticsearch and Kibana searches them by array, task or level."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-93"}},{"type":"paragraph","content":[{"type":"text","text":"Metrics: Prometheus scrapes every service and Grafana shows them. The single most important number is "},{"type":"text","text":"consumer lag","marks":[{"type":"bold"}]},{"type":"text","text":": how far the workers are behind."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-94"}},{"type":"paragraph","content":[{"type":"text","text":"Traces: the "},{"type":"text","text":"task_id","marks":[{"type":"code"}]},{"type":"text","text":" created at ingestion travels through every step, so one file''s whole journey can be followed end to end."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-95"}},{"type":"paragraph","content":[{"type":"text","text":"Alerts fire on: any message in the DLQ, a spike in quarantined files, rising retries, or growing lag. They go to Slack or PagerDuty."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-96"}},{"type":"callout","attrs":{"tone":"red","blockId":"telemetry-etl-pipeline-b-97"},"content":[{"type":"paragraph","content":[{"type":"text","text":"Logs go through Kafka, not straight to Elasticsearch, so a slow or broken Elasticsearch never slows down the pipeline. Search is briefly unavailable; data is not."}]}]},{"type":"heading","attrs":{"level":2,"sectionId":"telemetry-etl-pipeline-s-ag","frameId":"telemetry-etl-pipeline-frame-a6"},"content":[{"type":"text","text":"Decisions and trade-offs"}]},{"type":"paragraph","content":[{"type":"text","text":"Every design choice buys something and costs something. These six shaped the system:"}],"attrs":{"blockId":"telemetry-etl-pipeline-b-a7"}},{"type":"paragraph","content":[{"type":"text","text":"Kafka keyed by array: each array''s files stay in order and different arrays run in parallel. The cost: partitions cap the number of workers."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-a8"}},{"type":"paragraph","content":[{"type":"text","text":"Parse and load in one worker: atomic, simple, one hop shorter. The cost: parsing and loading cannot scale separately (not needed at this load)."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-a9"}},{"type":"paragraph","content":[{"type":"text","text":"At-least-once plus a duplicate check: nothing is lost and nothing is loaded twice. The cost: one small lookup per file."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-aa"}},{"type":"paragraph","content":[{"type":"text","text":"One primary with replicas, no sharding: simple to run with about 99% headroom. The cost: all writes depend on one primary (covered by automatic failover)."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-ab"}},{"type":"paragraph","content":[{"type":"text","text":"A separate archival service: parsing never waits on slow disk work. The cost: one more service to deploy and watch."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-ac"}},{"type":"paragraph","content":[{"type":"text","text":"Quarantine instead of retrying bad files: a broken file never blocks a lane. The cost: someone has to look at quarantined files."}],"attrs":{"blockId":"telemetry-etl-pipeline-b-ad"}},{"type":"callout","attrs":{"tone":"mint","blockId":"telemetry-etl-pipeline-b-ae"},"content":[{"type":"paragraph","content":[{"type":"text","text":"In one sentence:","marks":[{"type":"bold"}]},{"type":"text","text":" files are discovered once, queued per array in Kafka, loaded atomically and idempotently by stateless workers, archived only after verification, and every failure lands somewhere visible."}]}]},{"type":"details","attrs":{"tone":"sky","blockId":"telemetry-etl-pipeline-b-af"},"content":[{"type":"detailsSummary","content":[{"type":"text","text":"How it survives losing any single machine"}]},{"type":"detailsContent","content":[{"type":"paragraph","content":[{"type":"text","text":"Worker","marks":[{"type":"bold"}]},{"type":"text","text":" dies → Kafka gives its partitions to the others and redelivers the in-flight task."}]},{"type":"paragraph","content":[{"type":"text","text":"Kafka broker","marks":[{"type":"bold"}]},{"type":"text","text":" dies → every message has 3 copies (replication factor ≥ 3) on other brokers."}]},{"type":"paragraph","content":[{"type":"text","text":"PostgreSQL primary","marks":[{"type":"bold"}]},{"type":"text","text":" dies → a replica is promoted; workers retry for a few seconds."}]},{"type":"paragraph","content":[{"type":"text","text":"Redis","marks":[{"type":"bold"}]},{"type":"text","text":" dies → Sentinel promotes a replica; a few duplicate tasks may slip through and the database skips them."}]},{"type":"paragraph","content":[{"type":"text","text":"NAS","marks":[{"type":"bold"}]},{"type":"text","text":" unavailable → ingestion pauses and everything retries; files are never deleted before they are archived and verified."}]}]}]}]}'::jsonb, canvas = '{"layout":"40-60","files":{},"elements":[{"id":"telemetry-etl-pipeline-frame-1","type":"frame","x":0,"y":0,"width":1600,"height":1200,"name":"The problem","seed":1,"strokeColor":"#bbb","backgroundColor":"transparent","fillStyle":"solid","strokeWidth":2,"roughness":0,"opacity":100,"angle":0,"groupIds":[],"frameId":null,"roundness":null},{"id":"