update public.articles set title = 'A Distributed ETL Pipeline for Storage Telemetry', slug = null, summary = 'How 10,000+ storage arrays'' telemetry files flow into PostgreSQL 24×7 without losing, duplicating or reordering a single file: ingestion, Kafka, parser workers, archival, failures, and the trade-offs behind each choice.', tags = '{system-design,data-engineering,kafka}',
  reading_minutes = 10
where owner_id = '00000000-0000-4000-a000-000000000002' and public_id = 'EtlPipeline1';

insert into public.article_versions (article_id, version, doc, canvas)
select article_id, 1, doc, canvas from public.article_drafts where article_id = (select id from public.articles where owner_id = '00000000-0000-4000-a000-000000000002' and public_id = 'EtlPipeline1');
update public.articles set status = 'published', published_version = 1, published_at = now() - interval '1 day',
  published_draft_version = (select version from public.article_drafts where article_id = articles.id)
where owner_id = '00000000-0000-4000-a000-000000000002' and public_id = 'EtlPipeline1';

